-- Additive v2 foundation. Existing columns/rows retain their v1 meanings.
ALTER TABLE quiz ADD mode VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'QUIZ',
 ADD UNIQUE KEY uq_quiz_mode(id,mode), ADD CONSTRAINT ck_quiz_mode CHECK (mode IN ('QUIZ','SONG','VIETNAMESE_PUZZLE','RIDDLE','CLUES','IMAGE_WORD','ORDERING'));
ALTER TABLE question DROP CHECK ck_question_values,
 MODIFY option_a TEXT NULL, MODIFY option_b TEXT NULL, MODIFY option_c TEXT NULL, MODIFY option_d TEXT NULL,
 MODIFY correct_option VARCHAR(1) CHARACTER SET ascii COLLATE ascii_bin NULL,
 ADD schema_version INT NOT NULL DEFAULT 1, ADD mode VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'QUIZ', ADD payload JSON NULL,
 ADD UNIQUE KEY uq_source_mode(id,mode), ADD CONSTRAINT fk_question_mode FOREIGN KEY(quiz_id,mode) REFERENCES quiz(id,mode),
 ADD CONSTRAINT ck_question_values CHECK (schema_version IN (1,2) AND (schema_version=2 OR mode='QUIZ') AND order_index>0 AND CHAR_LENGTH(TRIM(content))>0 AND created_at_ms>=0 AND (deleted_at_ms IS NULL OR deleted_at_ms>=created_at_ms) AND ((mode='QUIZ' AND payload IS NULL AND correct_option IS NOT NULL AND correct_option IN ('A','B','C','D') AND option_a IS NOT NULL AND CHAR_LENGTH(TRIM(option_a))>0 AND option_b IS NOT NULL AND CHAR_LENGTH(TRIM(option_b))>0 AND option_c IS NOT NULL AND CHAR_LENGTH(TRIM(option_c))>0 AND option_d IS NOT NULL AND CHAR_LENGTH(TRIM(option_d))>0) OR (schema_version=2 AND option_a IS NULL AND option_b IS NULL AND option_c IS NULL AND option_d IS NULL AND correct_option IS NULL AND payload IS NOT NULL AND ((mode='RIDDLE' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["acceptedAnswers","matchingPolicy"],"properties":{"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}},"matchingPolicy":{"enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]}}}', payload)) OR (mode='SONG' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["acceptedAnswers","matchingPolicy","mediaRef"],"properties":{"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}},"matchingPolicy":{"enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]},"mediaRef":{"type":"string","pattern":"^sha256:[0-9a-f]{64}$"}}}', payload)) OR (mode='IMAGE_WORD' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["acceptedAnswers","matchingPolicy","mediaRef"],"properties":{"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}},"matchingPolicy":{"enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]},"mediaRef":{"type":"string","pattern":"^sha256:[0-9a-f]{64}$"}}}', payload)) OR (mode='CLUES' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["acceptedAnswers","matchingPolicy","hints"],"properties":{"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}},"matchingPolicy":{"enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]},"hints":{"type":"array","minItems":1,"maxItems":20,"items":{"type":"object","additionalProperties":false,"required":["offsetMs","text"],"properties":{"offsetMs":{"type":"integer","minimum":0},"text":{"type":"string","minLength":1,"maxLength":2000}}}}}}', payload)) OR (mode='VIETNAMESE_PUZZLE' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["pieces","correctOrder"],"properties":{"pieces":{"type":"array","minItems":2,"maxItems":100,"items":{"type":"object","additionalProperties":false,"required":["id","text"],"properties":{"id":{"type":"string","minLength":1,"maxLength":64},"text":{"type":"string","minLength":1,"maxLength":300}}}},"correctOrder":{"type":"array","minItems":2,"maxItems":100,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":64}}}}', payload)) OR (mode='ORDERING' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["items","correctOrder"],"properties":{"items":{"type":"array","minItems":2,"maxItems":100,"items":{"type":"object","additionalProperties":false,"required":["id","text"],"properties":{"id":{"type":"string","minLength":1,"maxLength":64},"text":{"type":"string","minLength":1,"maxLength":300}}}},"correctOrder":{"type":"array","minItems":2,"maxItems":100,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":64}}}}', payload))))));
ALTER TABLE game_session DROP CHECK ck_game_values, DROP CHECK ck_game_config, DROP CHECK ck_game_end,
 MODIFY quiz_id BIGINT NULL, MODIFY quiz_author_user_id BIGINT NULL, MODIFY quiz_title_snapshot VARCHAR(200) NULL, MODIFY config_snapshot JSON NULL,
 ADD schema_version INT NOT NULL DEFAULT 1, ADD rules_version INT NOT NULL DEFAULT 1, ADD v2_config_snapshot JSON NULL, ADD current_stage_index INT NOT NULL DEFAULT 0,
 ADD UNIQUE KEY uq_game_version(id,schema_version),
 ADD CONSTRAINT ck_game_values CHECK (schema_version IN (1,2) AND rules_version=schema_version AND status IN ('ACTIVE','FINISHED') AND phase IN ('INTRO','DECISION','QUESTION_OPEN','QUESTION_CLOSED','SCORING','RESULT','FINISHED') AND question_count BETWEEN IF(schema_version=1,10,1) AND 50 AND current_question_index BETWEEN 0 AND question_count AND current_stage_index BETWEEN 0 AND 7 AND (schema_version=2 OR (phase<>'INTRO' AND current_stage_index=0)) AND revision>=0 AND started_at_ms>=0 AND (phase_opened_at_ms IS NULL OR phase_opened_at_ms>=started_at_ms) AND (phase_deadline_at_ms IS NULL OR (phase_opened_at_ms IS NOT NULL AND phase_deadline_at_ms>=phase_opened_at_ms))),
 ADD CONSTRAINT ck_game_end CHECK ((status='ACTIVE' AND phase<>'FINISHED' AND end_reason IS NULL AND finished_at_ms IS NULL) OR (status='FINISHED' AND phase='FINISHED' AND finished_at_ms IS NOT NULL AND finished_at_ms>=started_at_ms AND end_reason IS NOT NULL AND end_reason IN ('COMPLETED','ONE_SURVIVOR','ALL_ELIMINATED','CANCELLED','SERVER_INTERRUPTED') AND (schema_version=1 OR end_reason IN ('COMPLETED','CANCELLED','SERVER_INTERRUPTED')))),
 ADD CONSTRAINT ck_game_config CHECK ((schema_version=1 AND quiz_id IS NOT NULL AND quiz_author_user_id IS NOT NULL AND quiz_title_snapshot IS NOT NULL AND CHAR_LENGTH(TRIM(quiz_title_snapshot))>0 AND config_snapshot IS NOT NULL AND v2_config_snapshot IS NULL AND (JSON_SCHEMA_VALID('{"type":"object","required":["schemaVersion","questionCount","questionDurationMs","decisionDurationMs","initialScore","spinCredits","starCredits","normal","starOnly","spins","streaks","spinWithoutReplacement","spinBeforeStarOnly","eliminationRule","rankingRule","endReasonPriority","allEliminatedRankOneAreWinners"],"properties":{"schemaVersion":{"enum":[1]},"questionCount":{"type":"integer","minimum":10,"maximum":50},"questionDurationMs":{"type":"integer","minimum":1},"decisionDurationMs":{"type":"integer","minimum":1},"initialScore":{"enum":[20]},"spinCredits":{"type":"integer","minimum":1,"maximum":5},"starCredits":{"enum":[1]},"normal":{"type":"object"},"starOnly":{"type":"object"},"spins":{"type":"object","required":["BONUS","SAFE","BREAKTHROUGH","SPEED","DECISIVE","HARDSHIP"]},"streaks":{"type":"object","required":["threshold","momentumBonus","recoveryReduction","recoveryPenaltyCap","recoveryUsesBasePenalty","recoveryConsumedWhenFinalPenaltyZero","newEffectAppliesOnTrigger","effectsStack","noAnswerResetsBothStreaks","eliminationBeforeStreakUpdate"],"properties":{"threshold":{"enum":[5]},"momentumBonus":{"enum":[3]},"recoveryReduction":{"enum":[3]},"recoveryPenaltyCap":{"enum":[0]},"recoveryUsesBasePenalty":{"enum":[true]},"recoveryConsumedWhenFinalPenaltyZero":{"enum":[true]},"newEffectAppliesOnTrigger":{"enum":[false]},"effectsStack":{"enum":[false]},"noAnswerResetsBothStreaks":{"enum":[true]},"eliminationBeforeStreakUpdate":{"enum":[true]}}},"spinWithoutReplacement":{"enum":[true]},"spinBeforeStarOnly":{"enum":[true]},"eliminationRule":{"enum":["SCORE_LT_ZERO"]},"rankingRule":{"enum":["SCORE_DESC_TIME_ASC_COMPETITION"]},"endReasonPriority":{"enum":["ALL_ELIMINATED_OR_ONE_SURVIVOR_BEFORE_COMPLETED"]},"allEliminatedRankOneAreWinners":{"enum":[true]}}}', config_snapshot)
        AND JSON_EXTRACT(config_snapshot, '$.questionCount') = question_count
        AND JSON_EXTRACT(config_snapshot, '$.spinCredits') = FLOOR(question_count / 10))) OR (schema_version=2 AND quiz_id IS NULL AND quiz_author_user_id IS NULL AND quiz_title_snapshot IS NULL AND config_snapshot IS NULL AND v2_config_snapshot IS NOT NULL AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["schemaVersion","rulesVersion","questionCount","quizQuestionCount","initialScore","minimumScore","spinCredits","starCredits","decisionDurationMs","introDurationMs","resultDurationMs","eliminationRule","rankingRule"],"properties":{"schemaVersion":{"enum":[2]},"rulesVersion":{"enum":[2]},"questionCount":{"type":"integer","minimum":1,"maximum":50},"quizQuestionCount":{"type":"integer","minimum":0,"maximum":50},"initialScore":{"enum":[0]},"minimumScore":{"enum":[0]},"spinCredits":{"type":"integer","minimum":0,"maximum":5},"starCredits":{"type":"integer","minimum":0,"maximum":1},"decisionDurationMs":{"enum":[7000]},"introDurationMs":{"enum":[10000]},"resultDurationMs":{"enum":[1500]},"eliminationRule":{"enum":["NONE"]},"rankingRule":{"enum":["SCORE_DESC_CORRECT_TIME_ASC_COMPETITION"]}}}', v2_config_snapshot) AND JSON_EXTRACT(v2_config_snapshot,'$.questionCount')=question_count AND JSON_EXTRACT(v2_config_snapshot,'$.quizQuestionCount')<=question_count AND JSON_EXTRACT(v2_config_snapshot,'$.spinCredits')=FLOOR(JSON_EXTRACT(v2_config_snapshot,'$.quizQuestionCount')/10) AND JSON_EXTRACT(v2_config_snapshot,'$.starCredits')=IF(JSON_EXTRACT(v2_config_snapshot,'$.quizQuestionCount')>0,1,0)));
CREATE TABLE game_stage (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, game_session_id BIGINT NOT NULL, schema_version INT NOT NULL DEFAULT 2,
 order_index INT NOT NULL, mode VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, source_quiz_id BIGINT NOT NULL,
 author_user_id BIGINT NOT NULL, title_snapshot VARCHAR(200) NOT NULL, first_question_index INT NOT NULL, question_count INT NOT NULL, question_duration_ms BIGINT NOT NULL, config_snapshot JSON NOT NULL,
 CONSTRAINT uq_stage_order UNIQUE(game_session_id,order_index), CONSTRAINT uq_stage_mode UNIQUE(game_session_id,mode), CONSTRAINT uq_stage_game_mode UNIQUE(game_session_id,id,mode),
 CONSTRAINT fk_stage_version FOREIGN KEY(game_session_id,schema_version) REFERENCES game_session(id,schema_version),
 CONSTRAINT fk_stage_source FOREIGN KEY(source_quiz_id,mode) REFERENCES quiz(id,mode), CONSTRAINT fk_stage_author FOREIGN KEY(author_user_id) REFERENCES app_user(id),
 CONSTRAINT ck_stage_values CHECK (schema_version=2 AND order_index BETWEEN 1 AND 7 AND first_question_index>=1 AND question_count BETWEEN 1 AND 50 AND first_question_index+question_count-1<=50 AND question_duration_ms>0 AND CHAR_LENGTH(TRIM(title_snapshot))>0 AND JSON_TYPE(config_snapshot)='OBJECT')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
ALTER TABLE player_session ADD schema_version INT NOT NULL DEFAULT 1, ADD total_correct_answer_time_ms BIGINT NULL,
 ADD CONSTRAINT fk_player_version FOREIGN KEY(game_session_id,schema_version) REFERENCES game_session(id,schema_version),
 ADD CONSTRAINT ck_player_v2 CHECK ((schema_version=1 AND total_correct_answer_time_ms IS NULL) OR (schema_version=2 AND player_state='PLAYING' AND score>=0 AND total_correct_answer_time_ms IS NOT NULL AND total_correct_answer_time_ms>=0 AND eliminated_at_ms IS NULL AND eliminated_question_index IS NULL));
ALTER TABLE game_question DROP CHECK ck_game_question_values,
 MODIFY option_a TEXT NULL, MODIFY option_b TEXT NULL, MODIFY option_c TEXT NULL, MODIFY option_d TEXT NULL, MODIFY correct_option VARCHAR(1) CHARACTER SET ascii COLLATE ascii_bin NULL,
 ADD schema_version INT NOT NULL DEFAULT 1, ADD mode VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'QUIZ', ADD stage_id BIGINT NULL, ADD stage_question_index INT NULL, ADD payload JSON NULL,
 ADD UNIQUE KEY uq_gq_version_mode(game_session_id,id,schema_version,mode), ADD UNIQUE KEY uq_gq_stage_order(stage_id,stage_question_index),
 ADD CONSTRAINT fk_gq_version FOREIGN KEY(game_session_id,schema_version) REFERENCES game_session(id,schema_version),
 ADD CONSTRAINT fk_gq_stage_mode FOREIGN KEY(game_session_id,stage_id,mode) REFERENCES game_stage(game_session_id,id,mode),
 ADD CONSTRAINT fk_gq_source_mode FOREIGN KEY(source_question_id,mode) REFERENCES question(id,mode),
 ADD CONSTRAINT ck_game_question_values CHECK (schema_version IN (1,2) AND order_index BETWEEN 1 AND 50 AND question_duration_ms>0 AND phase IN ('DECISION','QUESTION_OPEN','QUESTION_CLOSED','SCORING','RESULT') AND CHAR_LENGTH(TRIM(content))>0 AND (opened_at_ms IS NULL OR opened_at_ms>=0) AND (deadline_at_ms IS NULL OR (opened_at_ms IS NOT NULL AND deadline_at_ms>opened_at_ms)) AND (scored_at_ms IS NULL OR (opened_at_ms IS NOT NULL AND scored_at_ms>=opened_at_ms)) AND ((schema_version=1 AND mode='QUIZ' AND stage_id IS NULL AND stage_question_index IS NULL) OR (schema_version=2 AND stage_id IS NOT NULL AND stage_question_index IS NOT NULL AND stage_question_index BETWEEN 1 AND 50)) AND ((mode='QUIZ' AND payload IS NULL AND correct_option IS NOT NULL AND correct_option IN ('A','B','C','D') AND option_a IS NOT NULL AND CHAR_LENGTH(TRIM(option_a))>0 AND option_b IS NOT NULL AND CHAR_LENGTH(TRIM(option_b))>0 AND option_c IS NOT NULL AND CHAR_LENGTH(TRIM(option_c))>0 AND option_d IS NOT NULL AND CHAR_LENGTH(TRIM(option_d))>0) OR (schema_version=2 AND option_a IS NULL AND option_b IS NULL AND option_c IS NULL AND option_d IS NULL AND correct_option IS NULL AND payload IS NOT NULL AND ((mode='RIDDLE' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["acceptedAnswers","matchingPolicy"],"properties":{"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}},"matchingPolicy":{"enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]}}}', payload)) OR (mode='SONG' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["acceptedAnswers","matchingPolicy","mediaRef"],"properties":{"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}},"matchingPolicy":{"enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]},"mediaRef":{"type":"string","pattern":"^sha256:[0-9a-f]{64}$"}}}', payload)) OR (mode='IMAGE_WORD' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["acceptedAnswers","matchingPolicy","mediaRef"],"properties":{"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}},"matchingPolicy":{"enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]},"mediaRef":{"type":"string","pattern":"^sha256:[0-9a-f]{64}$"}}}', payload)) OR (mode='CLUES' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["acceptedAnswers","matchingPolicy","hints"],"properties":{"acceptedAnswers":{"type":"array","minItems":1,"maxItems":20,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}},"matchingPolicy":{"enum":["NFC_CASE_INSENSITIVE_WHITESPACE"]},"hints":{"type":"array","minItems":1,"maxItems":20,"items":{"type":"object","additionalProperties":false,"required":["offsetMs","text"],"properties":{"offsetMs":{"type":"integer","minimum":0},"text":{"type":"string","minLength":1,"maxLength":2000}}}}}}', payload)) OR (mode='VIETNAMESE_PUZZLE' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["pieces","correctOrder"],"properties":{"pieces":{"type":"array","minItems":2,"maxItems":100,"items":{"type":"object","additionalProperties":false,"required":["id","text"],"properties":{"id":{"type":"string","minLength":1,"maxLength":64},"text":{"type":"string","minLength":1,"maxLength":300}}}},"correctOrder":{"type":"array","minItems":2,"maxItems":100,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":64}}}}', payload)) OR (mode='ORDERING' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["items","correctOrder"],"properties":{"items":{"type":"array","minItems":2,"maxItems":100,"items":{"type":"object","additionalProperties":false,"required":["id","text"],"properties":{"id":{"type":"string","minLength":1,"maxLength":64},"text":{"type":"string","minLength":1,"maxLength":300}}}},"correctOrder":{"type":"array","minItems":2,"maxItems":100,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":64}}}}', payload))))));
ALTER TABLE answer DROP CHECK ck_answer_received, DROP CHECK ck_answer_effect_snapshot,
 ADD schema_version INT NOT NULL DEFAULT 1, ADD mode VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'QUIZ', ADD answer_kind VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'OPTION', ADD answer_payload JSON NULL,
 ADD CONSTRAINT fk_answer_version_mode FOREIGN KEY(game_session_id,game_question_id,schema_version,mode) REFERENCES game_question(game_session_id,id,schema_version,mode),
 ADD CONSTRAINT ck_answer_received CHECK ((answer_status='NO_ANSWER' AND selected_option IS NULL AND received_at_ms IS NULL AND answer_payload IS NULL) OR (answer_status<>'NO_ANSWER' AND received_at_ms IS NOT NULL AND ((answer_kind='OPTION' AND selected_option IS NOT NULL AND answer_payload IS NULL) OR (answer_kind<>'OPTION' AND selected_option IS NULL AND answer_payload IS NOT NULL)))),
 ADD CONSTRAINT ck_answer_kind CHECK ((schema_version=1 AND mode='QUIZ' AND answer_kind='OPTION') OR (schema_version=2 AND ((mode='QUIZ' AND answer_kind='OPTION') OR (mode IN ('SONG','RIDDLE','CLUES','IMAGE_WORD') AND answer_kind='TEXT') OR (mode IN ('VIETNAMESE_PUZZLE','ORDERING') AND answer_kind='ARRANGEMENT')))),
 ADD CONSTRAINT ck_answer_payload CHECK (answer_payload IS NULL OR (answer_kind='TEXT' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["text"],"properties":{"text":{"type":"string","minLength":1,"maxLength":300,"pattern":"\\\\S"}}}', answer_payload)) OR (answer_kind='ARRANGEMENT' AND JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["itemIds"],"properties":{"itemIds":{"type":"array","minItems":2,"maxItems":100,"uniqueItems":true,"items":{"type":"string","minLength":1,"maxLength":64}}}}', answer_payload))),
 ADD CONSTRAINT ck_answer_v2_result CHECK (schema_version=1 OR answer_status='ACCEPTED_UNSCORED' OR (score_after>=0 AND JSON_CONTAINS_PATH(result_snapshot,'all','$.schemaVersion','$.mode','$.correctAnswerTimeMs') AND JSON_EXTRACT(result_snapshot,'$.schemaVersion')=2 AND JSON_UNQUOTE(JSON_EXTRACT(result_snapshot,'$.mode'))=mode AND JSON_TYPE(JSON_EXTRACT(result_snapshot,'$.correctAnswerTimeMs'))='INTEGER' AND JSON_EXTRACT(result_snapshot,'$.correctAnswerTimeMs')=IF(answer_status='CORRECT',answer_time_ms,0))),
 ADD CONSTRAINT ck_answer_effect_snapshot CHECK (result_snapshot IS NULL OR (mode='QUIZ' AND JSON_SCHEMA_VALID('{"type":"object","required":["hasMomentumBefore","hasRecoveryBefore","hasMomentumAfter","hasRecoveryAfter"],"properties":{"hasMomentumBefore":{"type":"boolean"},"hasRecoveryBefore":{"type":"boolean"},"hasMomentumAfter":{"type":"boolean"},"hasRecoveryAfter":{"type":"boolean"}}}', result_snapshot)) OR (schema_version=2 AND mode<>'QUIZ' AND NOT JSON_CONTAINS_PATH(result_snapshot,'one','$.hasMomentumBefore','$.hasRecoveryBefore','$.hasMomentumAfter','$.hasRecoveryAfter') AND JSON_CONTAINS_PATH(result_snapshot,'all','$.schemaVersion','$.mode','$.correctAnswerTimeMs')));
DROP TRIGGER trg_game_snapshot_immutable;
DROP TRIGGER trg_game_question_immutable;
DELIMITER $$
CREATE TRIGGER trg_game_snapshot_immutable BEFORE UPDATE ON game_session FOR EACH ROW
BEGIN
    IF NOT (OLD.room_id <=> NEW.room_id) OR NOT (OLD.quiz_id <=> NEW.quiz_id)
        OR NOT (OLD.quiz_author_user_id <=> NEW.quiz_author_user_id)
        OR NOT (OLD.quiz_title_snapshot <=> NEW.quiz_title_snapshot)
        OR NOT (OLD.schema_version <=> NEW.schema_version) OR NOT (OLD.rules_version <=> NEW.rules_version) OR NOT (OLD.v2_config_snapshot <=> NEW.v2_config_snapshot)
        OR NOT (OLD.question_count <=> NEW.question_count) OR NOT (OLD.config_snapshot <=> NEW.config_snapshot) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Game content/config snapshot is immutable';
    END IF;
END$$
CREATE TRIGGER trg_game_question_immutable BEFORE UPDATE ON game_question FOR EACH ROW
BEGIN
    IF NOT (OLD.game_session_id <=> NEW.game_session_id) OR NOT (OLD.source_question_id <=> NEW.source_question_id)
        OR NOT (OLD.order_index <=> NEW.order_index) OR NOT (OLD.content <=> NEW.content)
        OR NOT (OLD.option_a <=> NEW.option_a) OR NOT (OLD.option_b <=> NEW.option_b)
        OR NOT (OLD.option_c <=> NEW.option_c) OR NOT (OLD.option_d <=> NEW.option_d)
        OR NOT (OLD.correct_option <=> NEW.correct_option) OR NOT (OLD.image_ref <=> NEW.image_ref)
        OR NOT (OLD.schema_version <=> NEW.schema_version) OR NOT (OLD.mode <=> NEW.mode) OR NOT (OLD.payload <=> NEW.payload) OR NOT (OLD.stage_id <=> NEW.stage_id) OR NOT (OLD.stage_question_index <=> NEW.stage_question_index)
        OR NOT (OLD.question_duration_ms <=> NEW.question_duration_ms) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Game question snapshot is immutable';
    END IF;
END$$
CREATE TRIGGER trg_stage_immutable BEFORE UPDATE ON game_stage FOR EACH ROW
BEGIN
 SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Game stage snapshot is immutable';
END$$
CREATE TRIGGER trg_quiz_mode_immutable BEFORE UPDATE ON quiz FOR EACH ROW
BEGIN
 IF NOT (OLD.mode <=> NEW.mode) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Question set mode is immutable'; END IF;
END$$
CREATE TRIGGER trg_gq_stage_insert BEFORE INSERT ON game_question FOR EACH ROW
BEGIN
 DECLARE first_index INT; DECLARE stage_count INT; DECLARE duration_ms BIGINT;
 IF NEW.schema_version=2 THEN
 SELECT first_question_index,question_count,question_duration_ms INTO first_index,stage_count,duration_ms FROM game_stage WHERE id=NEW.stage_id AND game_session_id=NEW.game_session_id AND mode=NEW.mode;
 IF first_index IS NULL OR NEW.stage_question_index>stage_count OR NEW.order_index<>first_index+NEW.stage_question_index-1 OR NEW.question_duration_ms<>duration_ms THEN
 SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Question must match its immutable stage'; END IF;
 END IF;
END$$
CREATE TRIGGER trg_stage_bounds BEFORE INSERT ON game_stage FOR EACH ROW
BEGIN
 DECLARE total_count INT; DECLARE actual_author BIGINT;
 SELECT question_count INTO total_count FROM game_session WHERE id=NEW.game_session_id;
 SELECT owner_user_id INTO actual_author FROM quiz WHERE id=NEW.source_quiz_id;
 IF NEW.first_question_index+NEW.question_count-1>total_count OR NEW.author_user_id<>actual_author THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid stage bounds/author'; END IF;
END$$
CREATE TRIGGER trg_player_version_immutable BEFORE UPDATE ON player_session FOR EACH ROW
BEGIN
 IF OLD.schema_version<>NEW.schema_version THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Player schema version is immutable'; END IF;
END$$
CREATE TRIGGER trg_answer_identity_immutable BEFORE UPDATE ON answer FOR EACH ROW
BEGIN
 IF OLD.schema_version<>NEW.schema_version OR OLD.mode<>NEW.mode OR OLD.answer_kind<>NEW.answer_kind OR OLD.game_session_id<>NEW.game_session_id OR OLD.player_session_id<>NEW.player_session_id OR OLD.game_question_id<>NEW.game_question_id OR NOT(OLD.answer_payload<=>NEW.answer_payload) OR NOT(OLD.selected_option<=>NEW.selected_option) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Accepted answer identity/input is immutable'; END IF;
END$$
DELIMITER ;
